<?php
declare(strict_types=1);
require __DIR__.'/../app/core.php';
session_start_safe();
$mutex=fopen(private_dir().'/install.mutex','c');flock($mutex,LOCK_EX);
// This check is deliberately outside the POST branch and runs on EVERY installer request.
if(is_file(private_dir().'/config.lock')||is_file(cfgpath())){http_response_code(409);echo '<h1>Setup locked</h1><p>An installation or configuration already exists. See README lock recovery. No data has been changed.</p><a href="index.php">Open website</a>';exit;}
$_SESSION['setup_csrf']=$_SESSION['setup_csrf']??bin2hex(random_bytes(32));
$error='';$success='';$values=$_POST;
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!hash_equals($_SESSION['setup_csrf'],$_POST['csrf']??''))throw new InvalidArgumentException('Invalid setup session. Reload and retry.');
 $type=$_POST['database']??'sqlite';if(!in_array($type,['sqlite','mysql'],true))throw new InvalidArgumentException('Choose SQLite or MySQL.');
 $c=['dsn'=>'sqlite:'.private_dir().'/vehicles.sqlite','db_user'=>null,'db_password'=>null];
 if($type==='mysql'){foreach(['db_host','db_name','db_user'] as $k)required($_POST,[$k]);if(!preg_match('/^[A-Za-z0-9_]+$/D',$_POST['db_name']))throw new InvalidArgumentException('Database name may contain only letters, digits and underscores.');$host=$_POST['db_host'];if(!preg_match('/^[A-Za-z0-9.:-]+$/D',$host))throw new InvalidArgumentException('Invalid database host.');$c=['dsn'=>'mysql:host='.$host.';dbname='.$_POST['db_name'].';charset=utf8mb4','db_user'=>$_POST['db_user'],'db_password'=>$_POST['db_password']??''];}
 $p=db($c);
 // Probe metadata, never application tables before schema creation. Any existing application table requires recovery, not a second installation.
 $exists=$type==='sqlite'?sql($p,"SELECT name FROM sqlite_master WHERE type='table' AND name IN ('meta','users','records')")->fetchColumn():sql($p,"SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('meta','users','records')")->fetchColumn();
 if($exists)throw new InvalidArgumentException('Existing database detected. Setup refuses to overwrite it. Use the documented data-preserving recovery procedure.');
 if(($_POST['operation']??'')==='test'){$success='Connection succeeded. No tables or administrator were created.';}
 else {
 required($_POST,['site_name','username','password','make','model','year','odometer','engine_miles','baseline_date']);if(strlen($_POST['password'])<12)throw new InvalidArgumentException('Use an administrator password of at least 12 characters.');if(!in_array($_POST['unit'],['mi','km'],true)||!preg_match('/^[A-Z]{3}$/D',$_POST['currency']))throw new InvalidArgumentException('Choose mi/km and a three-letter currency code.');
 // Validate all input before DDL (MySQL DDL commits implicitly).
 $vehicle=validate('vehicles',array_intersect_key($_POST,array_flip(['make','model','year','vin','plate','color','odometer','engine_miles','baseline_date'])),0,[]);
 schema($p);$p->beginTransaction();
 try{sql($p,'INSERT INTO users(username,password) VALUES(?,?)',[$_POST['username'],password_hash($_POST['password'],PASSWORD_DEFAULT)]);sql($p,'INSERT INTO meta(name,value) VALUES(?,?)',['installation_id',bin2hex(random_bytes(24))]);$now=gmdate('c');sql($p,'INSERT INTO records(kind,payload,created,updated) VALUES(?,?,?,?)',['vehicles',json_encode($vehicle),$now,$now]);
 $c+=['site_name'=>trim($_POST['site_name']),'currency'=>$_POST['currency'],'unit'=>$_POST['unit'],'github_owner'=>'','github_repo'=>''];$tmp=cfgpath().'.pending';if(file_put_contents($tmp,"<?php\nreturn ".var_export($c,true).";\n",LOCK_EX)===false)throw new RuntimeException('Cannot write configuration.');chmod($tmp,0600);$p->commit();
 if(!rename($tmp,cfgpath()))throw new RuntimeException('Database installed but configuration publication failed. Follow recovery; do not rerun setup.');if(file_put_contents(private_dir().'/config.lock',"Vehicle Tracker installed ".gmdate('c')."\n",LOCK_EX)===false)throw new RuntimeException('Configuration installed; lock write failed. Follow lock recovery.');chmod(private_dir().'/config.lock',0600);header('Location: index.php');exit;
 }catch(Throwable $e){if($p->inTransaction()){$p->rollBack(); // No preexisting application tables passed the guard. Remove only this failed new schema.
 foreach(['files','requests','revisions','records','tokens','users','meta'] as $table)$p->exec('DROP TABLE IF EXISTS '.$table);@unlink(cfgpath().'.pending');}throw $e;}
 }
}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'Setup failed: '.$e->getMessage();}
function h($s):string{return htmlspecialchars((string)($s??''),ENT_QUOTES,'UTF-8');}
function input($key,$label,$type='text',$default=''){global $values;echo '<label>'.h($label).'<input name="'.h($key).'" type="'.$type.'" value="'.h($type==='password'?'':($values[$key]??$default)).'"'.($type==='number'?' step="any" min="0"':'').'></label>';}
$catalogMeta=json_decode(file_get_contents(ROOT.'/data/catalog.json'),true);
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vehicle Tracker · Setup</title><link rel="stylesheet" href="style.css"><body><main class="setup"><div class="eyebrow">VEHICLE TRACKER / FIRST RUN</div><h1>Your garage, connected.</h1><p class="muted">One secure home for your vehicles, people and records. Complete these three steps to begin.</p><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif ?><?php if($success):?><p class="notice"><?=h($success)?></p><?php endif ?>
<form method="post" id="setup"><input type="hidden" name="csrf" value="<?=h($_SESSION['setup_csrf'])?>"><section class="card"><h2>1 · Database connection</h2><div class="grid"><label>Database<select name="database" id="database"><option value="sqlite">SQLite · simplest</option><option value="mysql" <?=($values['database']??'')==='mysql'?'selected':''?>>MySQL / MariaDB</option></select></label><?php input('db_host','MySQL host','text','localhost');input('db_name','Existing empty MySQL database','text','vehicle_tracker');input('db_user','MySQL username','text','root');input('db_password','MySQL password','password');?></div><button name="operation" value="test" class="secondary">Test connection only</button><p class="muted">SQLite is stored outside htdocs. For MySQL, create an empty database first; no table creation is needed.</p></section>
<section class="card"><h2>2 · Site & administrator</h2><div class="grid"><?php input('site_name','Site name','text','My Garage');input('username','Administrator username');input('password','Administrator password (12+ characters)','password');input('currency','Currency · ISO code','text','USD');?><label>Distance unit<select name="unit"><option value="mi">Miles</option><option value="km" <?=($values['unit']??'')==='km'?'selected':''?>>Kilometers</option></select></label></div></section>
<section class="card"><h2>3 · Your first vehicle</h2><p class="muted">Use the bundled offline catalog, or type any missing/custom make and model. Vehicle data by <a href="https://vehiclesdb.com">VehiclesDB</a> and NHTSA vPIC. Bundled catalog: <?=h($catalogMeta['make_count'])?> makes / <?=h($catalogMeta['model_count'])?> models. <?=h(($catalogMeta['complete_vpic_snapshot']??true)?'':'Fallback only; not the full requested snapshot.')?></p><div class="grid"><?php input('make','Make');input('model','Model');input('year','Year','number',(string)date('Y'));input('vin','VIN');input('plate','Plate');input('color','Color');input('baseline_date','Baseline date','date',date('Y-m-d'));input('odometer','Vehicle odometer','number','120000');input('engine_miles','Engine mileage at this baseline','number','25000');?></div></section><button name="operation" value="install">Create secure installation →</button></form><p class="muted">No default credentials. Setup locks permanently after success. Keep a backup of the private storage directory.</p></main><script>let catalog=[];fetch('../data/catalog.json').then(r=>r.json()).then(c=>{catalog=c.makes;let make=document.querySelector('[name=make]'),model=document.querySelector('[name=model]');function list(el,id,values){let d=document.getElementById(id)||document.body.appendChild(Object.assign(document.createElement('datalist'),{id}));d.replaceChildren(...values.map(v=>Object.assign(document.createElement('option'),{value:v})));el.setAttribute('list',id)}list(make,'makes',catalog.map(m=>m.name));make.addEventListener('input',()=>{model.value='';list(model,'models',(catalog.find(m=>m.name===make.value)?.models||[]).map(m=>m.name))});list(model,'models',(catalog.find(m=>m.name===make.value)?.models||[]).map(m=>m.name))}).catch(()=>{});</script></body></html>
